<script lang="ts">
 import {invoke} from '@tauri-apps/api/core';
 import {onMount} from 'svelte';
 import {openUrl} from '@tauri-apps/plugin-opener';
 import {mailText,type MailMessage} from './mail';
 import {safeMessageLink} from './message-body';
 import {renderMailHtml,mailHtmlDocument} from './mail-html';
 let {message,defaultPresentation="html",approvedImages={},onPresentation=()=>{}}:{message:MailMessage;defaultPresentation?:"html"|"plain";approvedImages?:Record<string,string>;onPresentation?:(plain:boolean)=>void}=$props();
 // A read-state refresh replaces the message object, not the reader's choice.
 let presentation=$state<{id:string;plain:boolean}|null>(null);
 const plain=$derived(presentation?.id===message.id?presentation.plain:defaultPresentation==='plain');
 let revision=$state(0),linkTarget=$state(''),error=$state('');
 $effect(()=>{onPresentation(plain||!isHtml);});
 const isHtml=$derived(message.body?.contentType?.toLowerCase()==='html');
 let external=$state<{id:string;images:Record<string,string>}>({id:'',images:{}}),externalBusy=$state(false),externalError=$state(''),intranetImage=$state('');
 const externalApproved=$derived(external.id===message.id?external.images:{});
 const rendered=$derived(isHtml?renderMailHtml(message.body?.content??'',{...approvedImages,...externalApproved}):null);
 async function loadExternal(url:string,allowIntranet=false){if(externalBusy)return;const id=message.id;externalBusy=true;externalError='';intranetImage='';try{const image=await invoke<string>('mail_external_image',{url,allowIntranet});if(message.id===id)external={id,images:{...externalApproved,[url]:image}};}catch(e){if(message.id===id){const reason=(e instanceof Error?e.message:String(e)).replace(/^Error: /,'');if(reason==='INTRANET_IMAGE_APPROVAL_REQUIRED'){intranetImage=url;externalError='This image is hosted on a private intranet. Load it only if you recognize this source.';}else{const known=['Invalid image address','Only public HTTPS images on the standard port can be loaded','Image host could not be resolved','Images on local, link-local or special networks are blocked','Image client unavailable','External image could not be loaded','Image server refused the request or requires a redirect. Open the email in Outlook to view it.','External image exceeds 5 MiB','Image download failed','Unsupported image content; only PNG, JPEG, GIF and WebP are allowed'];externalError=known.includes(reason)?reason:'Image could not be loaded. Restart TAUT if it was running before the image loader was added.';}}}finally{externalBusy=false;}}
 function blockExternal(url:string){const images={...externalApproved};delete images[url];external={id:message.id,images};}

 const doc=$derived.by(()=>{revision;const theme=getComputedStyle(document.documentElement);return rendered?mailHtmlDocument(rendered.html,{text:theme.getPropertyValue('--text-primary').trim(),background:theme.getPropertyValue('--surface-raised').trim(),border:theme.getPropertyValue('--border-strong').trim(),accent:theme.getPropertyValue('--accent').trim()}):'';});
 onMount(()=>{const observer=new MutationObserver(()=>revision++);observer.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme','data-contrast','data-accent','style','class']});return ()=>observer.disconnect();});
 async function openLink(){const url=safeMessageLink(linkTarget);if(!url)return;try{await openUrl(url);linkTarget='';}catch{error='The link could not be opened.';}}
</script>
{#if isHtml&&rendered?.hasContent}<div class="mail-format" role="group" aria-label="Email presentation"><button aria-pressed={!plain} onclick={()=>presentation={id:message.id,plain:false}}>HTML</button><button aria-pressed={plain} onclick={()=>presentation={id:message.id,plain:true}}>Plain text</button><small>Unapproved images blocked · numbered links below</small></div>{/if}
{#if rendered&&!rendered.hasContent}<p class="empty-body">This email has no readable message body. Open in Outlook for meeting or other message details.</p>
{:else if rendered&&!plain}
 <iframe title="Formatted email" sandbox="" referrerpolicy="no-referrer" srcdoc={doc}></iframe>
 {#if rendered.images}<p class="note">{rendered.images} blocked {rendered.images===1?'image':'images'}. External images have separate approval controls below. Attached inline images can be previewed from Attachments.</p>{/if}
 {#if rendered.shortened}<p class="note">Long or deeply nested content was shortened. Open in Outlook for the original.</p>{/if}
 {#if rendered.links.length}<details class="mail-disclosure"><summary>Email links ({rendered.links.length})</summary>{#each rendered.links as url,index}<button class="link" onclick={()=>{linkTarget=url;error='';}}><span>[{index+1}]</span> {url}</button>{/each}</details>{/if}
{:else}<div class="mail-body">{mailText(message)||'This message has no readable text. Open it in Outlook for the original presentation.'}</div>{/if}
{#if rendered?.externalImages.length}<details class="mail-disclosure external-images"><summary>External images ({rendered.externalImages.length})</summary><p class="note">Loading an image contacts its source and may tell the sender this email was opened. Approval applies only to this email while it is open.</p>{#each rendered.externalImages as image(image.url)}<div class="external-image"><span><strong>{image.alt}</strong><small>{image.domain}</small></span>{#if externalApproved[image.url]}<button onclick={()=>blockExternal(image.url)}>Block again</button>{:else}<button disabled={externalBusy} onclick={()=>loadExternal(image.url)}>{externalBusy?'Loading…':'Load for this email'}</button>{/if}</div>{/each}{#if externalError}<p role="alert">{externalError}</p>{/if}{#if intranetImage}<div class="intranet-review"><strong>{new URL(intranetImage).hostname}</strong><p class="note">This request will access your private network for this image only. It sends no Microsoft credentials or cookies.</p><button disabled={externalBusy} onclick={()=>loadExternal(intranetImage,true)}>Load this intranet image</button><button onclick={()=>{intranetImage='';externalError='';}}>Cancel</button></div>{/if}</details>{/if}
{#if linkTarget}<div class="link-review" role="group" aria-label="Review email link"><strong>Open this destination in your browser?</strong><p>{linkTarget}</p><button onclick={openLink}>Open link</button><button onclick={()=>linkTarget=''}>Cancel</button>{#if error}<p role="alert">{error}</p>{/if}</div>{/if}
<style>
.mail-disclosure{border:1px solid var(--border);border-radius:8px;padding:12px}.external-image{display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--border)}.external-image>span{flex:1;min-width:0;overflow-wrap:anywhere}.external-image small{display:block;margin-top:4px}.external-image button{flex:none}

.empty-body{font-size:13px;color:var(--text-secondary);line-height:1.7;margin:12px 0}.mail-format{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}button{padding:7px 10px;border:1px solid var(--border);border-radius:6px;color:var(--accent)}button[aria-pressed=true]{background:var(--accent)!important;color:var(--text-on-accent)!important;border-color:var(--accent)!important;font-weight:750;box-shadow:0 0 0 1px var(--accent)}button:focus-visible{outline:2px solid var(--accent);outline-offset:3px}small,.note{font-size:11px;color:var(--text-secondary);line-height:1.6}iframe{display:block;width:100%;height:clamp(260px,48vh,650px);border:1px solid var(--border);border-radius:8px;background:var(--surface-raised)}.mail-body{font-size:14px;line-height:1.8;white-space:pre-wrap;overflow-wrap:anywhere;padding:12px 0 20px}details{margin:12px 0;font-size:12px}summary{cursor:pointer;color:var(--accent)}.link{display:block;text-align:left;width:100%;margin:6px 0;overflow-wrap:anywhere}.link-review{border:1px solid var(--accent-border);padding:14px;border-radius:8px;margin:12px 0;font-size:12px}.link-review p{overflow-wrap:anywhere}.link-review button{margin-right:8px}
</style>
